
# --- portable paths (generated by export) -------------------------
# Everything below derives from the repo location; override with env vars
#   COMFYUI_DIR / COMFY_PYTHON / FOUNDRY_PYTHON
$FF_ROOT = if ($PSScriptRoot -and (Test-Path (Join-Path $PSScriptRoot 'app.py'))) {
    $PSScriptRoot
} else {
    Split-Path -Parent $PSScriptRoot
}
$FF_COMFY = if ($env:COMFYUI_DIR) { $env:COMFYUI_DIR } else { Join-Path (Split-Path -Parent $FF_ROOT) 'ComfyUI' }
$FF_COMFY_PY = if ($env:COMFY_PYTHON) { $env:COMFY_PYTHON } else { Join-Path $FF_COMFY 'python.exe' }
$FF_APP_PY = if ($env:FOUNDRY_PYTHON) { $env:FOUNDRY_PYTHON } else { 'python' }
$FF_LOG = Join-Path $FF_ROOT 'logs'
if (-not (Test-Path $FF_LOG)) { New-Item -ItemType Directory -Force -Path $FF_LOG | Out-Null }
# ------------------------------------------------------------------
# AI-Workshop one-click launcher (hardware-adaptive, 2026-09-05)
# Probes GPU/RAM/disk at startup, then launches the best-fitting ComfyUI topology:
#   dual-GPU (>=2 cards, >=16GB each) -> ComfyUI x2 (8188 GPU0 + 8189 GPU1, --reserve-vram 4)
#   single-GPU                        -> ComfyUI x1 (8188, no lowvram), image/video/3d serial
# NOTE: --use-sage-attention removed (Triton illegal-memory-access crashes on this box).
# NOTE: keep ASCII-only output to avoid PS5.1 encoding issues.

$ErrorActionPreference = "Continue"
$logDir = $FF_LOG
New-Item -ItemType Directory -Force -Path $logDir | Out-Null

function Test-Port($port) {
    $c = Get-NetTCPConnection -LocalPort $port -State Listen -ErrorAction SilentlyContinue
    return [bool]$c
}

Write-Host "=== AI Workshop launcher (hardware-adaptive) ===" -ForegroundColor Cyan

# ─────────────────────────────────────────────────────────
# 0. HARDWARE PROBE
# ─────────────────────────────────────────────────────────
Write-Host "[HW probe]" -ForegroundColor Cyan
$gpus = @(nvidia-smi -L 2>$null | Where-Object { $_ -match "GPU \d+:" })
$gpuCount = $gpus.Count
$gpuMemGB = @()
if ($gpuCount -ge 1) {
    $gpuMemGB = @(nvidia-smi --query-gpu=memory.total --format=csv,noheader,nounits 2>$null | ForEach-Object { [math]::Round([int]$_ / 1024) })
}
$os = Get-CimInstance Win32_OperatingSystem
$ramTotalGB = [math]::Round($os.TotalVisibleMemorySize / 1MB, 0)
$ramFreeGB  = [math]::Round($os.FreePhysicalMemory / 1MB, 0)
$diskFreeGB = [math]::Round((Get-PSDrive D -ErrorAction SilentlyContinue).Free / 1GB, 0)

Write-Host "  GPU : $gpuCount card(s), VRAM $($gpuMemGB -join '/') GB" -ForegroundColor Yellow
Write-Host "  RAM : $ramTotalGB GB total, $ramFreeGB GB free" -ForegroundColor Yellow
Write-Host "  Disk: D drive $diskFreeGB GB free" -ForegroundColor Yellow

# ─────────────────────────────────────────────────────────
# 0.5 ADAPTIVE DECISION
# ─────────────────────────────────────────────────────────
$dualGPU = ($gpuCount -ge 2) -and ($gpuMemGB.Count -ge 2) -and ($gpuMemGB[0] -ge 16) -and ($gpuMemGB[1] -ge 16)
if ($dualGPU) {
    Write-Host "  -> dual-GPU mode: ComfyUI x2 (8188 image + 8189 video/3d)" -ForegroundColor Green
} else {
    Write-Host "  -> single-GPU mode: ComfyUI x1 (8188, no lowvram), stages run serial" -ForegroundColor Green
}

# ─────────────────────────────────────────────────────────
# 0.6 GPU power limit 220W (crash protection)
# ─────────────────────────────────────────────────────────
& "$PSScriptRoot\scripts\set_power_limit.ps1"

# ─────────────────────────────────────────────────────────
# 0.7 Free port 8080 (prompt-LLM is timeshared; keep it empty)
# ─────────────────────────────────────────────────────────
$ll = Get-NetTCPConnection -LocalPort 8080 -State Listen -ErrorAction SilentlyContinue
if ($ll) {
    Stop-Process -Id $ll[0].OwningProcess -Force -ErrorAction SilentlyContinue
    Start-Sleep -Seconds 3
    Write-Host "  (0/3) freed port 8080 (PID $($ll[0].OwningProcess))" -ForegroundColor Yellow
} else {
    Write-Host "  (0/3) port 8080 free" -ForegroundColor Green
}

# ─────────────────────────────────────────────────────────
# 1. Ollama (optional — NOT required for DSH; llama-server handles prompts)
#    DSH can start regardless of Ollama state.
# ─────────────────────────────────────────────────────────
$ollamaRunning = Test-Port 11434
if ($ollamaRunning) {
    Write-Host "  (1/4) Ollama 11434 [online, optional]" -ForegroundColor Green
} else {
    Write-Host "  (1/4) Ollama 11434 [offline, optional — DSH uses llama-server on 8080]" -ForegroundColor Yellow
}

# ─────────────────────────────────────────────────────────
# 2. ComfyUI (required — image/video/3d generation)
# ─────────────────────────────────────────────────────────
$env:PYTHONPATH = $null
Remove-Item Env:PYTHONPATH -ErrorAction SilentlyContinue
# 2026-09-22 修「卡在开启 ComfyUI」：本脚本用 -RedirectStandardOutput 打开的是
# GBK(cp936) 文件流，不强制 UTF-8 时 ComfyUI 的 app/logger.py 一写 emoji(🎉) 就抛
# UnicodeEncodeError，异常从 print() 冒出 → **在绑定端口之前进程即死** → 8188 永不监听
# → 下面那段就绪等待必然超时。这两行是根因修复，其余流程保持原样。
$env:PYTHONIOENCODING = 'utf-8'
$env:PYTHONUTF8 = '1'
$env:PYTORCH_CUDA_ALLOC_CONF = 'max_split_size_mb:2048,expandable_segments:True'
$env:OMP_NUM_THREADS = '16'
$env:MKL_NUM_THREADS = '16'
$env:HF_ENDPOINT = 'https://hf-mirror.com'

if ($dualGPU) {
    # Instance A: GPU0 -> 8188 (image)
    if (Test-Port 8188) {
        Write-Host "  (3/4) ComfyUI 8188 already running" -ForegroundColor Green
    } else {
        Write-Host "  (3/4) ComfyUI 8188 (GPU0) starting..." -ForegroundColor Yellow
        $env:CUDA_VISIBLE_DEVICES = '0'
        Start-Process -FilePath $FF_COMFY_PY `
            -ArgumentList 'main.py','--port','8188','--reserve-vram','4' `
            -WorkingDirectory $FF_COMFY `
            -RedirectStandardOutput (Join-Path $logDir 'comfyui-8188-stdout.log') `
            -RedirectStandardError (Join-Path $logDir 'comfyui-8188-stderr.log') `
            -WindowStyle Hidden | Out-Null
    }
    # Instance B: GPU1 -> 8189 (video/3d)
    if (Test-Port 8189) {
        Write-Host "  (3/4) ComfyUI 8189 already running" -ForegroundColor Green
    } else {
        Write-Host "  (3/4) ComfyUI 8189 (GPU1) starting..." -ForegroundColor Yellow
        $env:CUDA_VISIBLE_DEVICES = '1'
        Start-Process -FilePath $FF_COMFY_PY `
            -ArgumentList 'main.py','--port','8189','--reserve-vram','4' `
            -WorkingDirectory $FF_COMFY `
            -RedirectStandardOutput (Join-Path $logDir 'comfyui-8189-stdout.log') `
            -RedirectStandardError (Join-Path $logDir 'comfyui-8189-stderr.log') `
            -WindowStyle Hidden | Out-Null
    }
    $t = 0
    while (-not ((Test-Port 8188) -and (Test-Port 8189)) -and $t -lt 150) { Start-Sleep -Seconds 2; $t += 2 }
    if ((Test-Port 8188) -and (Test-Port 8189)) { Write-Host "  (3/4) ComfyUI x2 OK (${t}s)" -ForegroundColor Green }
    else { Write-Host "  (3/4) ComfyUI x2 TIMEOUT, check $logDir" -ForegroundColor Red }
} else {
    # single-GPU: 8188, **do NOT use --lowvram**
    #
    # 2026-10-19 fix: image generation always failed with
    #   torch.AcceleratorError: CUDA error: operation not supported
    #   (crashed in comfy/samplers.py)
    #
    # Root cause: --lowvram splits model layers to CPU and swaps them in.
    #   This GPU is a V100 / sm_70, and some of the kernels used after splitting
    #   are not supported -> CUDA error at sampling time.
    #   Starting with --disable-cuda-malloc --use-pytorch-cross-attention works
    #   (same machine, same day: image OK in 102s, mesh OK with 34,410 faces).
    #
    # NOTE: keep this comment ASCII-only. PowerShell 5.1 reads this file as GBK
    #   and truncates non-ASCII text -> ParserError.
    if (Test-Port 8188) {
        Write-Host "  (3/4) ComfyUI 8188 already running" -ForegroundColor Green
    } else {
        Write-Host "  (3/4) ComfyUI 8188 (single-GPU) starting..." -ForegroundColor Yellow
        Start-Process -FilePath $FF_COMFY_PY `
            -ArgumentList 'main.py','--port','8188','--disable-cuda-malloc','--use-pytorch-cross-attention' `
            -WorkingDirectory $FF_COMFY `
            -RedirectStandardOutput (Join-Path $logDir 'comfyui-8188-stdout.log') `
            -RedirectStandardError (Join-Path $logDir 'comfyui-8188-stderr.log') `
            -WindowStyle Hidden | Out-Null
        $t = 0
        while (-not (Test-Port 8188) -and $t -lt 150) { Start-Sleep -Seconds 2; $t += 2 }
        if (Test-Port 8188) { Write-Host "  (3/4) ComfyUI 8188 OK (${t}s)" -ForegroundColor Green }
        else { Write-Host "  (3/4) ComfyUI 8188 TIMEOUT, check $logDir\comfyui-8188-stderr.log" -ForegroundColor Red }
    }
}

# ─────────────────────────────────────────────────────────
# 3. AI-Workshop app (miniconda3 python = py311 + gradio 5.50)
# ─────────────────────────────────────────────────────────
if (Test-Port 7860) {
    Write-Host "  (4/4) App already running (7860)" -ForegroundColor Green
} else {
    Write-Host "  (4/4) App starting..." -ForegroundColor Yellow
    Start-Process -FilePath $FF_APP_PY `
        -ArgumentList 'app.py' `
        -WorkingDirectory $FF_ROOT `
        -RedirectStandardOutput (Join-Path $logDir 'app-stdout.log') `
        -RedirectStandardError (Join-Path $logDir 'app-stderr.log') `
        -WindowStyle Hidden | Out-Null
    $t = 0
    while (-not (Test-Port 7860) -and $t -lt 60) { Start-Sleep -Seconds 2; $t += 2 }
    if (Test-Port 7860) { Write-Host "  (4/4) App OK -> http://localhost:7860" -ForegroundColor Green }
    else { Write-Host "  (4/4) App TIMEOUT, check $logDir\app-stderr.log" -ForegroundColor Red }
}

Write-Host "=== done ===" -ForegroundColor Cyan

if (Test-Port 7860) {
    Start-Process 'http://localhost:7860'
    Write-Host "Browser opened: http://localhost:7860" -ForegroundColor Green
}
